{
  "triples": [
    {
      "subject": "UCCA",
      "predicate": "uses",
      "object": "semantic representation",
      "object_type": "Concept",
      "source_sentence": "We use the UCCA scheme for semantic representation , where the semantic units are anchored in the text, which simplifies the splitting operation."
    },
    {
      "subject": "UCCA",
      "predicate": "uses",
      "object": "rule",
      "object_type": "Method",
      "source_sentence": "We further leverage the explicit distinction in UCCA between types of Scenes (events), applying a specific rule for each of the cases."
    },
    {
      "subject": "Models",
      "predicate": "addresses",
      "object": "sentence splitting",
      "object_type": "Task",
      "source_sentence": "None of these models explicitly addresses sentence splitting."
    },
    {
      "subject": "NMT",
      "predicate": "achieves",
      "object": "superior performance over PBMT in terms of BLEU and human evaluation scores",
      "object_type": "Other",
      "source_sentence": "The NTS NMT-based system (henceforth, N17) reported superior performance over PBMT in terms of BLEU and human evaluation scores, and serves as a component in our system."
    },
    {
      "subject": "NMT",
      "predicate": "uses",
      "object": "reinforcement learning",
      "object_type": "Method",
      "source_sentence": "Zhang and Lapata (2017) combined NMT with reinforcement learning, using SARI , BLEU, and cosine similarity to the source as the reward."
    }
  ]
}

{
  "triples": [
    {
      "subject": "hybrid",
      "predicate": "uses",
      "object": "semantic structures",
      "object_type": "Concept",
      "source_sentence": "Consequently, they proposed a supervised system (HYBRID) that uses semantic structures for sentence splitting and deletion."
    },
    {
      "subject": "Lexical Simplification",
      "predicate": "uses",
      "object": "Moses system",
      "object_type": "Model",
      "source_sentence": "Lexical simplification is performed using the Moses system."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Probabilistic Model",
      "predicate": "trainedOn",
      "object": "semantic structures of Simple Wikipedia",
      "object_type": "Other",
      "source_sentence": "where sentences are split based on a probabilistic model trained on the semantic structures of Simple Wikipedia as well as a language model trained on the same corpus."
    },
    {
      "subject": "Language Model",
      "predicate": "trainedOn",
      "object": "Simple Wikipedia corpus",
      "object_type": "Dataset",
      "source_sentence": "where sentences are split based on a probabilistic model trained on the semantic structures of Simple Wikipedia as well as a language model trained on the same corpus."
    },
    {
      "subject": "Lexical Simplification",
      "predicate": "uses",
      "object": "unsupervised model",
      "object_type": "Model",
      "source_sentence": "Lexical simplification is there performed using the unsupervised model of Biran et al."
    },
    {
      "subject": "rule-based simplification",
      "predicate": "uses",
      "object": "event extraction",
      "object_type": "Other",
      "source_sentence": "Stajner and Glavaš (2017) combined rule-based simplification conditioned on event extraction, together with an unsupervised lexical simplifier."
    },
    {
      "subject": "Parallel Corpus",
      "predicate": "uses",
      "object": "WebNLG dataset",
      "object_type": "Dataset",
      "source_sentence": "For this purpose they presented a specialized parallel corpus, derived from the WebNLG dataset."
    },
    {
      "subject": "Parallel Corpus",
      "predicate": "uses",
      "object": "DBpedia knowledge base",
      "object_type": "Other",
      "source_sentence": "The latter is obtained from the DBPedia knowledge base using content selection and crowdsourcing, and is annotated with semantic triplets of subject-relation-object, obtained semi-automatically."
    }
  ]
}

{
  "triples": [
    {
      "subject": "training",
      "predicate": "uses",
      "object": "Dropout",
      "object_type": "Method",
      "source_sentence": "Training is done with a 0.3 dropout probability."
    },
    {
      "subject": "Models",
      "predicate": "uses",
      "object": "Alignment",
      "object_type": "Method",
      "source_sentence": "This model uses alignment probabilities between the predictions and the original sentences , rather than character-based models, to retrieve the original words."
    },
    {
      "subject": "embeddings",
      "predicate": "trainedOn",
      "object": "Google News",
      "object_type": "Dataset",
      "source_sentence": "word2vec embeddings of size 300 are trained on Google News"
    },
    {
      "subject": "embeddings",
      "predicate": "trainedOn",
      "object": "training simplification corpus",
      "object_type": "Dataset",
      "source_sentence": "local embeddings of size 200 are trained on the training simplification corpus"
    },
    {
      "subject": "Beam Search",
      "predicate": "uses",
      "object": "Decoding",
      "object_type": "Method",
      "source_sentence": "beam search is performed during decoding by generating the first 5 hypotheses at each step ordered by the log-likelihood of the target sentence given the input sentence."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Grammaticality",
      "predicate": "uses",
      "object": "1 to 5 scale",
      "object_type": "Other",
      "source_sentence": "Grammaticality (G) and Meaning preservation (M) are measured using a 1 to 5 scale."
    },
    {
      "subject": "Grammaticality",
      "predicate": "uses",
      "object": "Identity transformation",
      "object_type": "Method",
      "source_sentence": "the grammaticality of the input is assessed by evaluating the Identity transformation"
    }
  ]
}

{
  "triples": [
    {
      "subject": "DSS",
      "predicate": "comparesAgainst",
      "object": "HYBRID",
      "object_type": "Model",
      "source_sentence": "We also compare the sentence splitting component used in our systems (namely DSS) to that used in HYBRID, abstracting away from deletion-based and lexical simplification."
    },
    {
      "subject": "DSS",
      "predicate": "achieves",
      "object": "46.45 BLEU",
      "object_type": "Metric",
      "source_sentence": "DSS gets a higher BLEU score (46.45 vs. 39.97) and performs more splittings (number of output sentences per input sentence of 1.73 vs."
    }
  ]
}

{
  "triples": [
    {
      "subject": "SENTS",
      "predicate": "uses",
      "object": "NMT",
      "object_type": "Method",
      "source_sentence": "Simplicity scores are much higher in the case of SENTS (that uses NMT), than with Moses."
    },
    {
      "subject": "SETrain1-Moses",
      "predicate": "uses",
      "object": "rules",
      "object_type": "Method",
      "source_sentence": "SETrain1-Moses, where a new training corpus is obtained by applying the splitting rules to the target side."
    },
    {
      "subject": "SETrain2-Moses",
      "predicate": "uses",
      "object": "rules",
      "object_type": "Method",
      "source_sentence": "SETrain2-Moses, where the rules are applied to the source side."
    }
  ]
}
